<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>抛体运动：初速度与角度</title>
<style>
  :root{--bg:#0f1720;--fg:#e8eef5;--accent:#4fc3f7;--muted:#8aa0b4;--panel:#18232e;
        --path:#4fc3f7;--apex:#ffb74d;--land:#66bb6a;--vec:#ef5350;}
  *{box-sizing:border-box;}
  body{margin:0;background:var(--bg);color:var(--fg);font-family:system-ui,-apple-system,"Segoe UI",sans-serif;padding:16px;}
  h1{font-size:1.15rem;margin:0 0 4px;}
  .sub{color:var(--muted);font-size:.85rem;margin-bottom:14px;line-height:1.5;}
  .wrap{display:grid;grid-template-columns:1fr 320px;gap:16px;align-items:start;}
  @media(max-width:820px){.wrap{grid-template-columns:1fr;}}
  .card{background:var(--panel);border:1px solid #263646;border-radius:10px;padding:10px;}
  canvas{width:100%;height:auto;display:block;border-radius:6px;background:#0b131b;}
  .panel{background:var(--panel);border:1px solid #263646;border-radius:10px;padding:14px;}
  .ctrl{margin-bottom:14px;}
  .ctrl:last-of-type{margin-bottom:0;}
  label{display:flex;justify-content:space-between;align-items:baseline;font-size:.9rem;margin-bottom:6px;}
  .val{color:var(--accent);font-variant-numeric:tabular-nums;font-weight:600;}
  input[type=range]{width:100%;accent-color:var(--accent);}
  .readout{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px;}
  .mini{background:#0b131b;border:1px solid #223141;border-radius:8px;padding:8px 10px;}
  .mini .k{font-size:.72rem;color:var(--muted);}
  .mini .v{font-size:.95rem;color:var(--accent);font-variant-numeric:tabular-nums;font-weight:600;}
  .mini.wide{grid-column:1 / -1;}
  .assume{font-size:.75rem;color:var(--muted);line-height:1.6;margin-top:12px;border-top:1px dashed #2c3d4e;padding-top:9px;}
  .assume b{color:#c7d6e4;}
  .legend{display:flex;flex-wrap:wrap;gap:10px;font-size:.75rem;color:var(--muted);margin-top:8px;}
  .legend i{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:4px;vertical-align:middle;}
  .hint{font-size:.75rem;color:var(--muted);margin-top:8px;line-height:1.5;}
</style>
</head>
<body>
  <h1>抛体运动：初速度与抛射角</h1>
  <div class="sub">无空气阻力，g = 9.8 m/s²。拖动滑块，观察轨迹形状、射程、最大高度与飞行时间。</div>

  <div class="wrap">
    <div class="card">
      <canvas id="cv" width="900" height="560" aria-label="抛体运动轨迹图"></canvas>
      <div class="legend">
        <span><i style="background:#4fc3f7"></i>轨迹</span>
        <span><i style="background:#ffb74d"></i>最高点</span>
        <span><i style="background:#66bb6a"></i>落地点</span>
        <span><i style="background:#ef5350"></i>初速度矢量</span>
      </div>
    </div>

    <div class="panel">
      <div class="ctrl">
        <label for="v0">初速度 v₀ <span class="val" id="v0Out">20.0 m/s</span></label>
        <input id="v0" type="range" min="5" max="60" step="0.5" value="20">
      </div>
      <div class="ctrl">
        <label for="ang">抛射角 θ <span class="val" id="angOut">45°</span></label>
        <input id="ang" type="range" min="5" max="85" step="1" value="45">
      </div>

      <div class="readout">
        <div class="mini"><div class="k">射程 R</div><div class="v" id="rangeV">40.8 m</div></div>
        <div class="mini"><div class="k">最大高度 H</div><div class="v" id="heightV">10.2 m</div></div>
        <div class="mini"><div class="k">飞行时间 T</div><div class="v" id="timeV">2.89 s</div></div>
        <div class="mini"><div class="k">最高点时刻</div><div class="v" id="apexT">1.44 s</div></div>
        <div class="mini wide"><div class="k">速度分量</div><div class="v" id="comp">vₓ = 14.1, v₀ᵧ = 14.1 m/s</div></div>
      </div>

      <div class="hint">提示：45° 时射程最大（固定 v₀）；θ 与 90°−θ 的射程相同，但最大高度和飞行时间不同。</div>

      <div class="assume">
        <b>数学假设：</b>从地面 (0,0) 以初速度 v₀、仰角 θ 抛出，仅受重力 g=9.8 m/s²，无空气阻力、无地球自转与曲率影响。
        水平匀速 \(x=v_0\cos\theta\cdot t\)，竖直匀变速 \(y=v_0\sin\theta\cdot t-\tfrac12gt^2\)。
        落回同一高度 y=0 时，飞行时间 \(T=2v_0\sin\theta/g\)，射程 \(R=v_0^2\sin2\theta/g\)，最大高度 \(H=v_0^2\sin^2\theta/(2g)\)。
      </div>
    </div>
  </div>

<script>
(function(){
  const cv = document.getElementById("cv");
  const ctx = cv.getContext("2d");
  const v0El = document.getElementById("v0");
  const angEl = document.getElementById("ang");
  const v0Out = document.getElementById("v0Out");
  const angOut = document.getElementById("angOut");
  const rangeV = document.getElementById("rangeV");
  const heightV = document.getElementById("heightV");
  const timeV = document.getElementById("timeV");
  const apexT = document.getElementById("apexT");
  const compEl = document.getElementById("comp");

  const G = 9.8;

  function restore(){
    let s = {};
    try { s = genui.getState() || {}; } catch(e){ s = {}; }
    v0El.value = (typeof s.v0 === "number") ? s.v0 : 20;
    angEl.value = (typeof s.ang === "number") ? s.ang : 45;
  }
  function save(){
    try {
      genui.setState({ v0: Number(v0El.value), ang: Number(angEl.value) });
    } catch(e){}
  }

  function niceStep(span, targetTicks){
    const raw = span / targetTicks;
    const mag = Math.pow(10, Math.floor(Math.log10(raw)));
    const norm = raw / mag;
    let step;
    if(norm < 1.5) step = 1;
    else if(norm < 3) step = 2;
    else if(norm < 7) step = 5;
    else step = 10;
    return step * mag;
  }

  function draw(){
    const v0 = Number(v0El.value);
    const deg = Number(angEl.value);
    const th = deg * Math.PI / 180;
    const vx = v0 * Math.cos(th);
    const vy = v0 * Math.sin(th);
    const T = 2 * vy / G;
    const R = v0 * v0 * Math.sin(2*th) / G;
    const H = vy * vy / (2*G);

    v0Out.textContent = v0.toFixed(1) + " m/s";
    angOut.textContent = deg + "°";
    rangeV.textContent = R.toFixed(1) + " m";
    heightV.textContent = H.toFixed(1) + " m";
    timeV.textContent = T.toFixed(2) + " s";
    apexT.textContent = (T/2).toFixed(2) + " s";
    compEl.textContent = "vₓ = " + vx.toFixed(1) + ", v₀ᵧ = " + vy.toFixed(1) + " m/s";

    const W = cv.width, Hc = cv.height;
    const pad = { l:60, r:24, t:24, b:44 };
    const plotW = W - pad.l - pad.r;
    const plotH = Hc - pad.t - pad.b;

    // 视图范围：x 留出余量，y 至少显示到最高点
    const xmax = Math.max(R * 1.12, 5);
    const ymax = Math.max(H * 1.25, 5);

    function w2s(x, y){
      return [
        pad.l + x / xmax * plotW,
        pad.t + (ymax - y) / ymax * plotH
      ];
    }

    ctx.clearRect(0,0,W,Hc);
    ctx.fillStyle = "#0b131b";
    ctx.fillRect(0,0,W,Hc);

    // 网格
    const xStep = niceStep(xmax, 8);
    const yStep = niceStep(ymax, 6);
    ctx.font = "11px system-ui, sans-serif";
    ctx.lineWidth = 1;

    for(let x = 0; x <= xmax + 1e-9; x += xStep){
      const [sx] = w2s(x, 0);
      ctx.strokeStyle = "#1b2a38";
      ctx.beginPath(); ctx.moveTo(sx, pad.t); ctx.lineTo(sx, pad.t + plotH); ctx.stroke();
      ctx.fillStyle = "#8aa0b4";
      ctx.textAlign = "center";
      ctx.fillText(formatTick(x), sx, pad.t + plotH + 16);
    }
    for(let y = 0; y <= ymax + 1e-9; y += yStep){
      const [, sy] = w2s(0, y);
      ctx.strokeStyle = "#1b2a38";
      ctx.beginPath(); ctx.moveTo(pad.l, sy); ctx.lineTo(pad.l + plotW, sy); ctx.stroke();
      ctx.fillStyle = "#8aa0b4";
      ctx.textAlign = "right";
      ctx.fillText(formatTick(y), pad.l - 7, sy + 4);
    }

    // 地面
    const [, syGround] = w2s(0, 0);
    ctx.strokeStyle = "#4a6480";
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(pad.l, syGround); ctx.lineTo(pad.l + plotW, syGround); ctx.stroke();
    // y 轴
    const [sx0] = w2s(0, 0);
    ctx.beginPath(); ctx.moveTo(sx0, pad.t); ctx.lineTo(sx0, pad.t + plotH); ctx.stroke();

    // 轨迹
    ctx.strokeStyle = "#4fc3f7";
    ctx.lineWidth = 2.6;
    ctx.lineJoin = "round";
    ctx.beginPath();
    const N = 400;
    for(let i=0;i<=N;i++){
      const t = T * i / N;
      const x = vx * t;
      const y = vy * t - 0.5 * G * t * t;
      const [sx, sy] = w2s(x, y);
      if(i===0) ctx.moveTo(sx, sy); else ctx.lineTo(sx, sy);
    }
    ctx.stroke();

    // 最高点
    {
      const xa = vx * (T/2);
      const [sxa, sya] = w2s(xa, H);
      ctx.fillStyle = "#ffb74d";
      ctx.beginPath(); ctx.arc(sxa, sya, 6, 0, Math.PI*2); ctx.fill();
      ctx.strokeStyle = "#0b131b"; ctx.lineWidth = 1.5; ctx.stroke();
      ctx.fillStyle = "#ffb74d";
      ctx.textAlign = "left";
      ctx.fillText("H = " + H.toFixed(1) + " m", sxa + 9, sya - 6);
    }

    // 落地点
    {
      const [sxl, syl] = w2s(R, 0);
      ctx.fillStyle = "#66bb6a";
      ctx.beginPath(); ctx.arc(sxl, syl, 6, 0, Math.PI*2); ctx.fill();
      ctx.strokeStyle = "#0b131b"; ctx.lineWidth = 1.5; ctx.stroke();
      ctx.fillStyle = "#66bb6a";
      ctx.textAlign = "center";
      ctx.fillText("R = " + R.toFixed(1) + " m", sxl, syl + 22);
    }

    // 初速度矢量
    {
      const [sx0b, sy0b] = w2s(0, 0);
      const scale = Math.min(plotW / (xmax * 1.4), plotH / (ymax * 1.4));
      const ex = sx0b + vx * scale * 0.35;
      const ey = sy0b - vy * scale * 0.35;
      ctx.strokeStyle = "#ef5350";
      ctx.lineWidth = 2.5;
      ctx.beginPath(); ctx.moveTo(sx0b, sy0b); ctx.lineTo(ex, ey); ctx.stroke();
      // 箭头
      const dx = ex - sx0b, dy = ey - sy0b;
      const len = Math.hypot(dx, dy) || 1;
      const ux = dx/len, uy = dy/len;
      const ah = 10;
      ctx.beginPath();
      ctx.moveTo(ex, ey);
      ctx.lineTo(ex - ux*ah - uy*ah*0.55, ey - uy*ah + ux*ah*0.55);
      ctx.lineTo(ex - ux*ah + uy*ah*0.55, ey - uy*ah - ux*ah*0.55);
      ctx.closePath();
      ctx.fillStyle = "#ef5350";
      ctx.fill();
      // 角度弧
      ctx.strokeStyle = "rgba(239,83,80,0.6)";
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(sx0b, sy0b, Math.min(46, len*0.55), -th, 0);
      ctx.stroke();
      ctx.fillStyle = "#ef5350";
      ctx.textAlign = "left";
      ctx.fillText("v₀ = " + v0.toFixed(1) + " m/s, θ = " + deg + "°", ex + 8, ey - 2);
    }

    // 轴标签
    ctx.fillStyle = "#8aa0b4";
    ctx.textAlign = "center";
    ctx.fillText("水平距离 x (m)", pad.l + plotW/2, Hc - 8);
    ctx.save();
    ctx.translate(16, pad.t + plotH/2);
    ctx.rotate(-Math.PI/2);
    ctx.fillText("高度 y (m)", 0, 0);
    ctx.restore();
  }

  function formatTick(v){
    const r = Math.round(v*1000)/1000;
    return Number.isInteger(r) ? String(r) : r.toFixed(1);
  }

  function onChange(){ draw(); save(); }

  v0El.addEventListener("input", onChange);
  angEl.addEventListener("input", onChange);

  restore();
  draw();
  save();
})();
</script>
</body>
</html>

怎么读这个实验

初速度 v₀ 增大：轨迹整体变大，射程、最大高度、飞行时间都随之增大（射程正比于 v₀²，高度与飞行时间也按比例增长）。

抛射角 θ：固定 v₀ 时，θ = 45° 射程最大；θ 与 90° − θ（如 30° 与 60°）射程相同，但角度越大最大高度越高、飞行时间越长。

速度分解：读数区给出水平分量 vₓ = v₀cosθ 与竖直分量 v₀ᵧ = v₀sinθ；水平分量决定射程，竖直分量决定停留时间和高度。

最高点（橙色）出现在 t = T/2，此时竖直速度为零；落地点（绿色）回到与抛出点相同高度。

假设说明

抛体从地面 (0,0) 抛出，落回同一高度 y = 0，地面水平。

仅受重力作用，g = 9.8 m/s² 恒定，忽略空气阻力、风、地球自转与曲率。

初速度 v₀∈[5,60] m/s，抛射角 θ∈[5°,85°]，因此始终有向上的竖直分量，不会出现向下抛射或垂直上抛的边界情况。

使用解析公式计算 T、R、H：T = 2v₀sinθ/g，R = v₀²sin2θ/g，H = v₀²sin²θ/(2g)；轨迹按 x = v₀cosθ·t、y = v₀sinθ·t − ½gt² 采样 400 点绘制。

视图按当前射程与最大高度自动定标，网格步长取整；初速度矢量箭头长度为示意比例，弧线表示抛射角。
